    def get_query_plan_ontology_compiler_sidecar_relation_realization_path(
        self,
        plan_path: str = None,
    ) -> str:
        configured_path = getattr(
            self.global_config,
            "query_plan_ontology_compiler_sidecar_relation_realization_path",
            None,
        )
        if configured_path:
            return str(configured_path)
        if plan_path:
            return os.path.join(os.path.dirname(plan_path), "relation_realization_map.json")
        return ""

    def _load_query_plan_relation_realization_map(
        self,
        plan_path: str,
        realization_path: str,
        *,
        artifact_label: str,
    ) -> Dict[str, Any]:
        if not realization_path or not os.path.exists(realization_path):
            logger.info("No %s relation realization map found at %s", artifact_label, realization_path)
            return {}

        with open(realization_path, "r", encoding="utf-8") as handle:
            realization_data = json.load(handle)
        if not isinstance(realization_data, dict):
            return {}

        strict_contract = bool(getattr(
            self.global_config,
            "query_plan_relation_realization_require_ontology_hash_match",
            False,
        ))
        with open(plan_path, "rb") as handle:
            current_plan_sha256 = hashlib.sha256(handle.read()).hexdigest()
        artifact_plan_sha256 = str(realization_data.get("query_plan_sha256", "") or "")
        if strict_contract and not artifact_plan_sha256:
            raise ValueError(
                f"{artifact_label} relation realization artifact has no query_plan_sha256"
            )
        if artifact_plan_sha256 and artifact_plan_sha256 != current_plan_sha256:
            raise ValueError(
                f"{artifact_label} relation realization artifact was built from a different ontology "
                f"(artifact={artifact_plan_sha256[:12]} current={current_plan_sha256[:12]})"
            )

        artifact_openie_sha256 = str(realization_data.get("openie_results_sha256", "") or "")
        if strict_contract and not artifact_openie_sha256:
            raise ValueError(
                f"{artifact_label} relation realization artifact has no openie_results_sha256"
            )
        if artifact_openie_sha256:
            if not os.path.isfile(self.openie_results_path):
                raise ValueError(
                    "runtime OpenIE results are missing; cannot validate relation realization artifact "
                    f"({self.openie_results_path})"
                )
            with open(self.openie_results_path, "rb") as handle:
                current_openie_sha256 = hashlib.sha256(handle.read()).hexdigest()
            if artifact_openie_sha256 != current_openie_sha256:
                raise ValueError(
                    f"{artifact_label} relation realization artifact was built from different OpenIE results "
                    f"(artifact={artifact_openie_sha256[:12]} current={current_openie_sha256[:12]})"
                )

        diag = realization_data.get("diagnostics", {})
        logger.info(
            "Loaded %s relation realization map from %s (plans=%s realized_steps=%s realized_relations=%s)",
            artifact_label,
            realization_path,
            diag.get("plan_count", "?"),
            diag.get("realized_steps", "?"),
            diag.get("realized_relations", "?"),
        )
        return realization_data

