    def prepare_query_plan_ontology(self):
        self.query_plan_ontology_matcher = None
        self.query_plan_ontology_compiler_sidecar_matcher = None
        self.query_plan_relation_realization_map = {}
        self.query_plan_ontology_compiler_sidecar_relation_realization_map = {}
        self.query_plan_projected_graph_retriever = None
        self.query_plan_evidence_index_retriever = None
        self.query_plan_path_executor_retriever = None
        if not getattr(self.global_config, "enable_query_plan_ontology", False):
            return

        plan_path = self.get_query_plan_ontology_path()
        if not os.path.exists(plan_path):
            logger.warning("Query plan ontology enabled but file not found: %s", plan_path)
            return

        require_certified_mask = bool(getattr(
            self.global_config,
            "query_plan_ontology_require_certified_schema_mask",
            False,
        ))
        deployment_policy = None
        certified_ids = set()
        try:
            self.query_plan_ontology_matcher = QueryPlanOntologyMatcher.load(plan_path)
            policy_path = self.get_query_plan_certified_direct_policy_path()
            apply_deployment_policy = bool(getattr(
                self.global_config,
                "query_plan_ontology_enable_certified_direct_execution",
                False,
            )) or require_certified_mask
            if require_certified_mask and (not policy_path or not os.path.isfile(policy_path)):
                raise FileNotFoundError(
                    "Certified schema mask is required but its deployment policy "
                    f"is unavailable: {policy_path or '<unset>'}"
                )
            if apply_deployment_policy and policy_path and os.path.isfile(policy_path):
                with open(policy_path, "r", encoding="utf-8") as handle:
                    deployment_policy = json.load(handle)
                expected_hash = str(deployment_policy.get("ontology_sha256", "") or "")
                if require_certified_mask and expected_hash:
                    with open(plan_path, "rb") as handle:
                        actual_hash = hashlib.sha256(handle.read()).hexdigest()
                    if actual_hash != expected_hash:
                        raise ValueError(
                            "Certified schema policy does not match the active ontology "
                            f"(policy={expected_hash[:12]} active={actual_hash[:12]})"
                        )
                routing_policy = dict(
                    deployment_policy.get("routing_policy", {}) or {}
                )
                if routing_policy:
                    self.query_plan_ontology_matcher.routing_model["policy"] = (
                        routing_policy
                    )
                    logger.info(
                        "Loaded frozen Q_cal routing policy from %s", policy_path
                    )
                certified_ids = set(
                    (deployment_policy.get("deployment_mask", {}) or {}).get(
                        "certified_schema_ids", []
                    ) or []
                )
                if require_certified_mask and not certified_ids:
                    raise ValueError(
                        f"Certified schema policy has an empty deployment mask: {policy_path}"
                    )
                mask_stats = self.query_plan_ontology_matcher.restrict_to_plan_ids(
                    certified_ids
                )
                if require_certified_mask and not mask_stats["after"]:
                    raise ValueError(
                        "The certified deployment mask retained no active ontology schemas"
                    )
                logger.info(
                    "Applied pre-routing frozen Q_val mask from %s "
                    "(certified=%d before=%d after=%d)",
                    policy_path,
                    len(certified_ids),
                    mask_stats["before"],
                    mask_stats["after"],
                )
            logger.info("Loaded query plan ontology from %s", plan_path)
        except Exception as e:
            if require_certified_mask:
                raise
            logger.warning("Failed to load query plan ontology from %s: %s", plan_path, e)

        sidecar_plan_path = self.get_query_plan_ontology_compiler_sidecar_path()
        if sidecar_plan_path:
            if not os.path.exists(sidecar_plan_path):
                raise FileNotFoundError(
                    f"Proposal-only compiler ontology not found: {sidecar_plan_path}"
                )
            self.query_plan_ontology_compiler_sidecar_matcher = QueryPlanOntologyMatcher.load(
                sidecar_plan_path
            )
            if certified_ids:
                sidecar_mask_stats = (
                    self.query_plan_ontology_compiler_sidecar_matcher.restrict_to_plan_ids(
                        certified_ids
                    )
                )
                if require_certified_mask and not sidecar_mask_stats["after"]:
                    raise ValueError(
                        "The certified deployment mask retained no compiler-sidecar schemas"
                    )
                logger.info(
                    "Applied frozen Q_val mask to compiler sidecar "
                    "(before=%d after=%d)",
                    sidecar_mask_stats["before"],
                    sidecar_mask_stats["after"],
                )
            logger.info(
                "Loaded proposal-only compiler ontology from %s; incumbent ontology remains %s",
                sidecar_plan_path,
                plan_path,
            )

        if not getattr(self.global_config, "query_plan_use_relation_realization", True):
            return

        try:
            realization_path = self.get_query_plan_relation_realization_path(plan_path)
            self.query_plan_relation_realization_map = (
                self._load_query_plan_relation_realization_map(
                    plan_path,
                    realization_path,
                    artifact_label="incumbent ontology",
                )
            )
            if sidecar_plan_path:
                sidecar_realization_path = (
                    self.get_query_plan_ontology_compiler_sidecar_relation_realization_path(
                        sidecar_plan_path
                    )
                )
                self.query_plan_ontology_compiler_sidecar_relation_realization_map = (
                    self._load_query_plan_relation_realization_map(
                        sidecar_plan_path,
                        sidecar_realization_path,
                        artifact_label="proposal-only compiler ontology",
                    )
                )
        except Exception as e:
            self.query_plan_relation_realization_map = {}
            self.query_plan_ontology_compiler_sidecar_relation_realization_map = {}
            logger.warning("Failed to load query plan relation realization artifacts: %s", e)
            if bool(getattr(
                self.global_config,
                "query_plan_relation_realization_require_ontology_hash_match",
                False,
            )):
                raise

