    def save_query_ontology_prior_trace(self) -> None:
        trace_path = getattr(self.global_config, "query_ontology_prior_trace_path", None)
        if not trace_path or not self.query_ontology_prior_trace_records:
            return
        try:
            trace_dir = os.path.dirname(trace_path)
            if trace_dir:
                os.makedirs(trace_dir, exist_ok=True)
            with open(trace_path, "w", encoding="utf-8") as trace_file:
                for record in self.query_ontology_prior_trace_records:
                    trace_file.write(json.dumps(record, ensure_ascii=False) + "\n")
            logger.info(
                "Saved query ontology prior trace with %d records to %s",
                len(self.query_ontology_prior_trace_records),
                trace_path,
            )
        except Exception as e:
            logger.warning("Failed to save query ontology prior trace to %s: %s", trace_path, e)

    def save_query_plan_ontology_trace(self) -> None:
        trace_path = getattr(self.global_config, "query_plan_ontology_trace_path", None)
