    def get_query_text_for_embedding(self, query: str, target: str) -> str:
        if self.ontology_query_expander is None:
            return query
        if self.get_ontology_embedding_weight() <= 0.001:
            return query
        mode = self.global_config.ontology_embedding_mode
        if mode == "none":
            return query
        if mode == "fact" and target != "fact":
            return query
        if mode == "passage" and target != "passage":
            return query
        if mode not in {"fact", "passage", "both"}:
            logger.warning("Unknown ontology_embedding_mode=%s; using original query.", mode)
            return query
        return self.ontology_query_expander.augment_query(query)

    @staticmethod
    def _normalize_embedding_rows(embeddings: np.ndarray) -> np.ndarray:
        embeddings = np.asarray(embeddings)
        norms = np.linalg.norm(embeddings, axis=1, keepdims=True)
        return np.divide(embeddings, norms, out=np.zeros_like(embeddings), where=norms > 0)

    def get_ontology_embedding_weight(self) -> float:
        weight = float(getattr(self.global_config, "ontology_embedding_weight", 1.0))
        return min(max(weight, 0.0), 1.0)

    def get_ontology_fact_boost_weight(self) -> float:
        weight = float(getattr(self.global_config, "ontology_fact_boost_weight", 0.0))
        return min(max(weight, 0.0), 1.0)

    @staticmethod
    def _parse_fact_content(content: Any) -> Tuple[str, str, str] | None:
        if isinstance(content, tuple) and len(content) == 3:
            return tuple(text_processing(list(content)))
        if isinstance(content, list) and len(content) == 3:
            return tuple(text_processing(content))
        if not isinstance(content, str):
            return None
        try:
            parsed = ast.literal_eval(content)
        except (SyntaxError, ValueError):
            return None
        if isinstance(parsed, (tuple, list)) and len(parsed) == 3:
            return tuple(text_processing(list(parsed)))
        return None

    def prepare_ontology_fact_index(self):
        if self.ontology_fact_index is not None:
            return

        entity_to_fact_indices = defaultdict(list)
        relation_to_fact_indices = defaultdict(list)
        relation_family_to_fact_indices = defaultdict(list)
        token_to_entities = defaultdict(set)
        entity_to_tokens = {}
        fact_triples = [None] * len(self.fact_node_keys)
        fact_rows = self.fact_embedding_store.get_rows(self.fact_node_keys)
        parsed_fact_count = 0

        for fact_idx, fact_id in enumerate(self.fact_node_keys):
            row = fact_rows.get(fact_id, {})
            triple = self._parse_fact_content(row.get("content"))
            if triple is None:
                continue
            subject, relation, obj = triple
            fact_triples[fact_idx] = triple
            parsed_fact_count += 1

            for entity in {subject, obj}:
                if entity:
                    entity_to_fact_indices[entity].append(fact_idx)
                    if entity not in entity_to_tokens:
                        entity_tokens = set(tokenize(entity))
                        entity_to_tokens[entity] = entity_tokens
                        for token in entity_tokens:
                            token_to_entities[token].add(entity)
            if relation:
                relation_to_fact_indices[relation].append(fact_idx)
                relation_family = _relation_family(relation)
                if relation_family:
                    relation_family_to_fact_indices[relation_family].append(fact_idx)

        self.ontology_fact_index = {
            "entities": {
                entity: np.array(indices, dtype=np.intp)
                for entity, indices in entity_to_fact_indices.items()
            },
            "relations": {
                relation: np.array(indices, dtype=np.intp)
                for relation, indices in relation_to_fact_indices.items()
            },
            "relation_families": {
                relation_family: np.array(indices, dtype=np.intp)
                for relation_family, indices in relation_family_to_fact_indices.items()
            },
            "entity_tokens": entity_to_tokens,
            "token_to_entities": {
                token: sorted(entities)
                for token, entities in token_to_entities.items()
            },
            "fact_triples": fact_triples,
        }
        logger.info(
            "Prepared ontology fact hint index with %d parsed facts, %d entities, %d relations.",
            parsed_fact_count,
            len(self.ontology_fact_index["entities"]),
            len(self.ontology_fact_index["relations"]),
        )

    def apply_ontology_fact_boost(self, query: str, query_fact_scores: np.ndarray) -> np.ndarray:
        try:
            boost_weight = self.get_ontology_fact_boost_weight()
            if boost_weight <= 0.001 or self.ontology_query_expander is None or len(query_fact_scores) == 0:
                return query_fact_scores

            hints = self.ontology_query_expander.analyze_query(query)
            matched_entities = [text_processing(entity) for entity in hints.get("entities", [])]
            matched_relations = [text_processing(relation) for relation in hints.get("relations", [])]
            if self.global_config.ontology_require_entity_match and not matched_entities:
                return query_fact_scores

            self.prepare_ontology_fact_index()
            entity_index = self.ontology_fact_index["entities"]
            relation_index = self.ontology_fact_index["relations"]
            max_facts_per_hint = int(getattr(self.global_config, "ontology_fact_boost_max_facts_per_hint", 500))

            boost = np.zeros_like(query_fact_scores, dtype=np.float32)
            entity_fact_indices = set()
            for entity in matched_entities:
                indices = entity_index.get(entity)
                if indices is None or len(indices) == 0:
                    continue
                if max_facts_per_hint > 0 and len(indices) > max_facts_per_hint:
                    continue
                entity_fact_indices.update(indices.tolist())
                boost[indices] += 1.0 / np.sqrt(len(indices))

            if not entity_fact_indices:
                return query_fact_scores

            relation_fact_indices = set()
            for relation in matched_relations:
                indices = relation_index.get(relation)
                if indices is None or len(indices) == 0:
                    continue
                if max_facts_per_hint > 0 and len(indices) > max_facts_per_hint:
                    continue
                relation_fact_indices.update(indices.tolist())

            if relation_fact_indices:
                anchored_relation_indices = np.array(
                    sorted(entity_fact_indices & relation_fact_indices),
                    dtype=np.intp,
                )
                if len(anchored_relation_indices) > 0:
                    boost[anchored_relation_indices] += 1.0

            if np.count_nonzero(boost) == 0:
                return query_fact_scores

            boost = min_max_normalize(boost)
            combined_scores = (1.0 - boost_weight) * query_fact_scores + boost_weight * boost
            return min_max_normalize(combined_scores)
        except Exception as e:
            logger.warning("Ontology fact boost failed; using original fact scores. Error: %s", e)
            return query_fact_scores

    @staticmethod
    def _query_aware_tokens(value: Any) -> Set[str]:
        stopwords = {
            "a", "an", "and", "are", "as", "at", "be", "by", "for", "from",
            "has", "had", "in", "is", "it", "its", "of", "on", "or", "that",
            "the", "to", "was", "were", "when", "where", "which", "who",
            "whom", "whose", "with", "what", "did", "does", "do", "both",
            "same", "many", "how", "her", "his", "him", "their", "them",
        }
        return {
            token
            for token in text_processing(value).split()
            if len(token) > 2 and token not in stopwords
        }

    def _query_aware_fact_score(
        self,
        query_tokens: Set[str],
        query_entities: Set[str],
        query_relations: Set[str],
        anchor_entities: Set[str],
        fact_idx: int,
        fact_triple: Tuple[str, str, str],
        query_fact_scores: np.ndarray,
    ) -> float | None:
        subject, relation, obj = fact_triple
        fact_entities = {subject, obj}
        if not (fact_entities & anchor_entities):
            return None

        fact_tokens = self._query_aware_tokens(" ".join(fact_triple))
        relation_tokens = self._query_aware_tokens(relation)

        query_entity_hits = len(fact_entities & query_entities)
        anchor_entity_hits = len(fact_entities & anchor_entities)
        introduces_new_entity = bool(fact_entities - anchor_entities)
        relation_exact_hit = relation in query_relations
        relation_token_overlap = relation_tokens & query_tokens
        fact_token_overlap = fact_tokens & query_tokens

        relation_score = 0.0
        if relation_exact_hit:
            relation_score = 1.0
        elif relation_tokens:
            relation_score = len(relation_token_overlap) / len(relation_tokens)



        if query_entity_hits == 0 and relation_score < 0.5 and not introduces_new_entity:
            return None

        token_overlap_score = len(fact_token_overlap) / max(len(fact_tokens), 1)
        base_score = float(query_fact_scores[fact_idx])
        bridge_score = (
            base_score
            + 0.35 * min(query_entity_hits, 2)
            + 0.20 * min(anchor_entity_hits, 2)
            + 0.30 * relation_score
            + 0.15 * float(introduces_new_entity)
            + 0.10 * token_overlap_score
        )
        return bridge_score

    def expand_query_aware_facts(
        self,
        query: str,
        query_fact_scores: np.ndarray,
        top_k_fact_indices: List[int],
        top_k_facts: List[Tuple],
    ) -> Tuple[List[int], List[Tuple], np.ndarray, Dict[str, Any]]:
        expansion_log = {
            "enabled": False,
            "added_fact_count": 0,
            "candidate_count": 0,
        }

        if not getattr(self.global_config, "enable_query_aware_fact_expansion", False):
            return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log
        expansion_log["enabled"] = True

        if self.ontology_query_expander is None or len(query_fact_scores) == 0 or len(self.fact_node_keys) == 0:
            return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

        try:
            self.prepare_ontology_fact_index()
            fact_triples = self.ontology_fact_index.get("fact_triples", [])
            entity_index = self.ontology_fact_index.get("entities", {})
            hints = self.ontology_query_expander.analyze_query(query)

            query_entities = {
                text_processing(entity)
                for entity in hints.get("entities", [])
                if text_processing(entity)
            }
            query_relations = {
                text_processing(relation)
                for relation in hints.get("relations", [])
                if text_processing(relation)
            }
            query_tokens = self._query_aware_tokens(query)
            for relation in query_relations:
                query_tokens.update(self._query_aware_tokens(relation))

            selected_indices = set(int(idx) for idx in top_k_fact_indices)
            anchor_entities = set(query_entities)
            normalized_top_facts = []
            for fact in top_k_facts:
                parsed = self._parse_fact_content(fact)
                if parsed is None:
                    continue
                normalized_top_facts.append(parsed)
                anchor_entities.update([parsed[0], parsed[2]])

            if not anchor_entities:
                return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

            candidate_top_k = max(int(getattr(self.global_config, "query_aware_candidate_top_k", 80)), 0)
            candidate_indices = set()
            if candidate_top_k > 0:
                candidate_indices.update(np.argsort(query_fact_scores)[-candidate_top_k:][::-1].tolist())

            max_facts_per_entity = int(getattr(self.global_config, "query_aware_max_facts_per_entity", 120))
            skipped_entity_count = 0
            for entity in anchor_entities:
                indices = entity_index.get(entity)
                if indices is None or len(indices) == 0:
                    continue
                if max_facts_per_entity > 0 and len(indices) > max_facts_per_entity:
                    skipped_entity_count += 1
                    continue
                candidate_indices.update(indices.tolist())

            expansion_log["candidate_count"] = len(candidate_indices)
            expansion_log["skipped_entity_count"] = skipped_entity_count

            scored_candidates = []
            for candidate_idx in candidate_indices:
                candidate_idx = int(candidate_idx)
                if candidate_idx in selected_indices:
                    continue
                if candidate_idx < 0 or candidate_idx >= len(fact_triples):
                    continue
                fact_triple = fact_triples[candidate_idx]
                if fact_triple is None:
                    continue

                bridge_score = self._query_aware_fact_score(
                    query_tokens=query_tokens,
                    query_entities=query_entities,
                    query_relations=query_relations,
                    anchor_entities=anchor_entities,
                    fact_idx=candidate_idx,
                    fact_triple=fact_triple,
                    query_fact_scores=query_fact_scores,
                )
                if bridge_score is not None:
                    scored_candidates.append((bridge_score, candidate_idx, fact_triple))

            if not scored_candidates:
                return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

            max_added_facts = max(int(getattr(self.global_config, "query_aware_max_added_facts", 5)), 0)
            if max_added_facts <= 0:
                return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

            scored_candidates.sort(reverse=True, key=lambda item: item[0])
            added = scored_candidates[:max_added_facts]
            added_indices = [candidate_idx for _, candidate_idx, _ in added]
            added_facts = [fact_triple for _, _, fact_triple in added]

            expanded_scores = np.array(query_fact_scores, copy=True)
            if top_k_fact_indices:
                anchor_score = float(np.max(query_fact_scores[top_k_fact_indices]))
            else:
                dense_anchor_count = min(5, len(query_fact_scores))
                anchor_score = float(np.max(np.sort(query_fact_scores)[-dense_anchor_count:]))

            score_weight = float(getattr(self.global_config, "query_aware_score_weight", 0.20))
            score_weight = min(max(score_weight, 0.0), 1.0)
            for candidate_idx in added_indices:
                raised_score = (1.0 - score_weight) * expanded_scores[candidate_idx] + score_weight * anchor_score
                expanded_scores[candidate_idx] = max(expanded_scores[candidate_idx], raised_score)

            expansion_log["added_fact_count"] = len(added_indices)
            expansion_log["added_fact_indices"] = added_indices

            return (
                list(top_k_fact_indices) + added_indices,
                list(top_k_facts) + added_facts,
                expanded_scores,
                expansion_log,
            )
        except Exception as e:
            logger.warning("Query-aware fact expansion failed; using reranked facts only. Error: %s", e)
            expansion_log["error"] = str(e)
            return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

    @staticmethod
    def _extract_json_object(text: Any) -> Dict[str, Any]:
        if isinstance(text, dict):
            return text
        if not isinstance(text, str):
            return {}

        cleaned = text.strip()
        if cleaned.startswith("```"):
            cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned, flags=re.IGNORECASE)
            cleaned = re.sub(r"\s*```$", "", cleaned).strip()

        for candidate in (cleaned, cleaned.replace("\n", " ")):
            try:
                parsed = json.loads(candidate)
                return parsed if isinstance(parsed, dict) else {}
            except json.JSONDecodeError:
                pass
            try:
                parsed = ast.literal_eval(candidate)
                return parsed if isinstance(parsed, dict) else {}
            except (SyntaxError, ValueError):
                pass

        decoder = json.JSONDecoder()
        for start in [match.start() for match in re.finditer(r"\{", cleaned)]:
            try:
                parsed, _ = decoder.raw_decode(cleaned[start:])
                if isinstance(parsed, dict):
                    return parsed
            except json.JSONDecodeError:
                continue
        return {}

    @staticmethod
    def _safe_int_list(value: Any) -> List[int]:
        if value is None:
            return []
        if isinstance(value, (int, np.integer)):
            return [int(value)]
        if not isinstance(value, list):
            return []
        parsed_values = []
        for item in value:
            try:
                parsed_values.append(int(item))
            except (TypeError, ValueError):
                continue
        return parsed_values

    @staticmethod
    def _shorten_for_prompt(value: Any, max_chars: int) -> str:
        text = str(value).replace("\r", " ").strip()
        text = re.sub(r"\s+", " ", text)
        if max_chars > 0 and len(text) > max_chars:
            return text[:max_chars].rstrip() + "..."
        return text

    def _query_local_ontology_agent_call(
        self,
        agent_name: str,
        system_prompt: str,
        payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        max_tokens = int(getattr(self.global_config, "query_local_ontology_max_completion_tokens", 512))
        max_tokens = max(max_tokens, 128)
        messages = [
            {"role": "system", "content": system_prompt},
            {
                "role": "user",
                "content": (
                    "Input JSON:\n"
                    + json.dumps(payload, ensure_ascii=False)
                    + "\nReturn only one valid JSON object."
                ),
            },
        ]
        try:
            response = self.llm_model.infer(
                messages=messages,
                max_completion_tokens=max_tokens,
                temperature=0,
            )
            response_text = response[0] if isinstance(response, tuple) else response
            parsed = self._extract_json_object(response_text)
            if not parsed:
                logger.debug("Query-local ontology %s returned no parseable JSON: %s", agent_name, response_text)
            return parsed
        except Exception as e:
            logger.warning("Query-local ontology %s failed; continuing without its output. Error: %s", agent_name, e)
            return {}

    @staticmethod
    def _query_local_agent_prompt(agent_name: str) -> str:
        prompts = {
            "entity_agent": (
                "You are the Entity Agent in a Saturn-style multi-agent ontology builder for graph QA. "
                "Identify the concrete entities, answer type, and constraints needed by the query. "
                "Use only names supported by the candidate facts/passages. "
                "Return JSON with keys: query_entities, candidate_entities, answer_type, constraints."
            ),
            "relation_agent": (
                "You are the Relation Agent in a Saturn-style multi-agent ontology builder for graph QA. "
                "Infer which relation types and hop directions are needed to answer the query, using only the supplied candidates. "
                "Return JSON with keys: relations, relation_aliases, required_hops. "
                "Each relation item should include name, direction, and evidence_fact_ids when possible."
            ),
            "bridge_agent": (
                "You are the Bridge Agent in a Saturn-style multi-agent ontology builder for graph QA. "
                "Select only candidate fact ids that can bridge the query entities toward the answer. "
                "Do not invent facts or ids. Prefer facts that add a useful missing hop rather than repeat already selected facts. "
                "Return JSON with keys: bridge_fact_ids, bridge_relations, rationale."
            ),
            "verifier_agent": (
                "You are the Verifier Agent in a Saturn-style multi-agent ontology builder for graph QA. "
                "Verify proposed bridge facts against the candidate facts/passages. "
                "Accept a fact id only if it is explicitly present in the candidates and is useful for the query. "
                "If uncertain, reject it. Do not invent facts or ids. "
                "Return JSON with keys: accepted_fact_ids, rejected_fact_ids, accepted_relations, reason."
            ),
        }
        return prompts[agent_name]

    def _build_query_local_ontology_context(
        self,
        query: str,
        query_fact_scores: np.ndarray,
        top_k_fact_indices: List[int],
    ) -> Tuple[List[Dict[str, Any]], Dict[int, int], List[Dict[str, Any]]]:
        self.prepare_ontology_fact_index()
        fact_triples = self.ontology_fact_index.get("fact_triples", [])

        candidate_top_k = max(int(getattr(self.global_config, "query_local_ontology_candidate_top_k", 24)), 0)
        selected_indices = [int(idx) for idx in top_k_fact_indices if 0 <= int(idx) < len(fact_triples)]
        dense_indices = []
        if candidate_top_k > 0 and len(query_fact_scores) > 0:
            dense_indices = np.argsort(query_fact_scores)[-candidate_top_k:][::-1].tolist()

        ordered_indices = []
        seen_indices = set()
        for candidate_idx in selected_indices + dense_indices:
            candidate_idx = int(candidate_idx)
            if candidate_idx in seen_indices or candidate_idx < 0 or candidate_idx >= len(fact_triples):
                continue
            fact_triple = fact_triples[candidate_idx]
            if fact_triple is None:
                continue
            ordered_indices.append(candidate_idx)
            seen_indices.add(candidate_idx)

        selected_index_set = set(selected_indices)
        candidate_facts = []
        prompt_id_to_fact_idx = {}
        for prompt_id, fact_idx in enumerate(ordered_indices):
            subject, relation, obj = fact_triples[fact_idx]
            prompt_id_to_fact_idx[prompt_id] = fact_idx
            candidate_facts.append({
                "id": prompt_id,
                "fact_index": fact_idx,
                "fact": [subject, relation, obj],
                "score": round(float(query_fact_scores[fact_idx]), 6) if len(query_fact_scores) > fact_idx else 0.0,
                "reranked": fact_idx in selected_index_set,
            })

        passage_snippets = []
        top_passages = max(int(getattr(self.global_config, "query_local_ontology_top_passages", 2)), 0)
        passage_chars = max(int(getattr(self.global_config, "query_local_ontology_passage_chars", 600)), 0)
        if top_passages > 0 and len(self.passage_node_keys) > 0:
            try:
                sorted_doc_ids, sorted_doc_scores = self.dense_passage_retrieval(query)
                for rank, doc_idx in enumerate(sorted_doc_ids[:top_passages].tolist()):
                    passage_key = self.passage_node_keys[int(doc_idx)]
                    passage_row = self.chunk_embedding_store.get_row(passage_key)
                    passage_snippets.append({
                        "rank": rank + 1,
                        "score": round(float(sorted_doc_scores[rank]), 6),
                        "text": self._shorten_for_prompt(passage_row.get("content", ""), passage_chars),
                    })
            except Exception as e:
                logger.debug("Could not collect query-local passage snippets: %s", e)

        return candidate_facts, prompt_id_to_fact_idx, passage_snippets

    def expand_query_local_ontology_facts(
        self,
        query: str,
        query_fact_scores: np.ndarray,
        top_k_fact_indices: List[int],
        top_k_facts: List[Tuple],
    ) -> Tuple[List[int], List[Tuple], np.ndarray, Dict[str, Any]]:
        expansion_log = {
            "enabled": False,
            "candidate_count": 0,
            "added_fact_count": 0,
        }

        if not getattr(self.global_config, "enable_query_local_ontology", False):
            return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log
        expansion_log["enabled"] = True

        if len(query_fact_scores) == 0 or len(self.fact_node_keys) == 0:
            return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

        try:
            candidate_facts, prompt_id_to_fact_idx, passage_snippets = self._build_query_local_ontology_context(
                query=query,
                query_fact_scores=query_fact_scores,
                top_k_fact_indices=top_k_fact_indices,
            )
            expansion_log["candidate_count"] = len(candidate_facts)
            expansion_log["passage_count"] = len(passage_snippets)

            if not candidate_facts:
                return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

            base_payload = {
                "query": query,
                "candidate_facts": candidate_facts,
                "top_passages": passage_snippets,
                "already_selected_fact_ids": [
                    fact["id"] for fact in candidate_facts if fact.get("reranked")
                ],
            }

            entity_state = self._query_local_ontology_agent_call(
                "entity_agent",
                self._query_local_agent_prompt("entity_agent"),
                base_payload,
            )
            relation_state = self._query_local_ontology_agent_call(
                "relation_agent",
                self._query_local_agent_prompt("relation_agent"),
                {**base_payload, "entity_agent": entity_state},
            )
            bridge_state = self._query_local_ontology_agent_call(
                "bridge_agent",
                self._query_local_agent_prompt("bridge_agent"),
                {**base_payload, "entity_agent": entity_state, "relation_agent": relation_state},
            )
            verifier_state = self._query_local_ontology_agent_call(
                "verifier_agent",
                self._query_local_agent_prompt("verifier_agent"),
                {
                    **base_payload,
                    "entity_agent": entity_state,
                    "relation_agent": relation_state,
                    "bridge_agent": bridge_state,
                },
            )

            accepted_prompt_ids = self._safe_int_list(verifier_state.get("accepted_fact_ids"))
            selected_fact_indices = set(int(idx) for idx in top_k_fact_indices)
            added_indices = []
            added_facts = []
            fact_triples = self.ontology_fact_index.get("fact_triples", [])
            max_added_facts = max(int(getattr(self.global_config, "query_local_ontology_max_added_facts", 5)), 0)

            for prompt_id in accepted_prompt_ids:
                if len(added_indices) >= max_added_facts:
                    break
                fact_idx = prompt_id_to_fact_idx.get(prompt_id)
                if fact_idx is None or fact_idx in selected_fact_indices:
                    continue
                fact_triple = fact_triples[fact_idx] if fact_idx < len(fact_triples) else None
                if fact_triple is None:
                    continue
                added_indices.append(fact_idx)
                added_facts.append(fact_triple)
                selected_fact_indices.add(fact_idx)

            expansion_log["proposed_fact_ids"] = self._safe_int_list(bridge_state.get("bridge_fact_ids"))
            expansion_log["accepted_prompt_fact_ids"] = accepted_prompt_ids
            expansion_log["accepted_fact_indices"] = added_indices
            expansion_log["added_fact_count"] = len(added_indices)
            expansion_log["accepted_relations"] = verifier_state.get("accepted_relations", [])

            if not added_indices:
                return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

            expanded_scores = np.array(query_fact_scores, copy=True)
            if top_k_fact_indices:
                anchor_score = float(np.max(query_fact_scores[top_k_fact_indices]))
            else:
                dense_anchor_count = min(5, len(query_fact_scores))
                anchor_score = float(np.max(np.sort(query_fact_scores)[-dense_anchor_count:]))

            score_weight = float(getattr(self.global_config, "query_local_ontology_score_weight", 0.60))
            score_weight = min(max(score_weight, 0.0), 1.0)
            for fact_idx in added_indices:
                raised_score = (1.0 - score_weight) * expanded_scores[fact_idx] + score_weight * anchor_score
                expanded_scores[fact_idx] = max(expanded_scores[fact_idx], raised_score)

            return (
                list(top_k_fact_indices) + added_indices,
                list(top_k_facts) + added_facts,
                expanded_scores,
                expansion_log,
            )
        except Exception as e:
            logger.warning("Query-local ontology expansion failed; using existing facts only. Error: %s", e)
            expansion_log["error"] = str(e)
            return top_k_fact_indices, top_k_facts, query_fact_scores, expansion_log

    def encode_query_embeddings_for_target(self, queries: List[str], target: str) -> np.ndarray:
        instruction = get_query_instruction(f"query_to_{target}")
        ontology_weight = self.get_ontology_embedding_weight()

        ontology_inputs = [
            self.get_query_text_for_embedding(query, target=target)
            for query in queries
        ]

        if ontology_weight >= 0.999 or all(text == query for text, query in zip(ontology_inputs, queries)):
            return self.embedding_model.batch_encode(
                ontology_inputs,
                instruction=instruction,
                norm=True,
            )

        if ontology_weight <= 0.001:
            return self.embedding_model.batch_encode(
                queries,
                instruction=instruction,
                norm=True,
            )

        logger.info(
            "Blending original and ontology query embeddings for %s with ontology_weight=%.3f.",
            target,
            ontology_weight,
        )
        original_embeddings = self.embedding_model.batch_encode(
            queries,
            instruction=instruction,
            norm=True,
        )
        ontology_embeddings = self.embedding_model.batch_encode(
            ontology_inputs,
            instruction=instruction,
            norm=True,
        )
        blended_embeddings = (1.0 - ontology_weight) * original_embeddings + ontology_weight * ontology_embeddings
        return self._normalize_embedding_rows(blended_embeddings)

    def get_query_embeddings(self, queries: List[str] | List[QuerySolution]):
        """
        Retrieves embeddings for given queries and updates the internal query-to-embedding mapping. The method determines whether each query
        is already present in the `self.query_to_embedding` dictionary under the keys 'triple' and 'passage'. If a query is not present in
        either, it is encoded into embeddings using the embedding model and stored.

        Args:
            queries List[str] | List[QuerySolution]: A list of query strings or QuerySolution objects. Each query is checked for
            its presence in the query-to-embedding mappings.
        """

        all_query_strings = []
        for query in queries:
            if isinstance(query, QuerySolution) and (
                    query.question not in self.query_to_embedding['triple'] or query.question not in
                    self.query_to_embedding['passage']):
                all_query_strings.append(query.question)
            elif query not in self.query_to_embedding['triple'] or query not in self.query_to_embedding['passage']:
                all_query_strings.append(query)

        if len(all_query_strings) > 0:

            logger.info(f"Encoding {len(all_query_strings)} queries for query_to_fact.")
            query_embeddings_for_triple = self.encode_query_embeddings_for_target(all_query_strings, target="fact")
            for query, embedding in zip(all_query_strings, query_embeddings_for_triple):
                self.query_to_embedding['triple'][query] = embedding

            logger.info(f"Encoding {len(all_query_strings)} queries for query_to_passage.")
            query_embeddings_for_passage = self.encode_query_embeddings_for_target(all_query_strings, target="passage")
            for query, embedding in zip(all_query_strings, query_embeddings_for_passage):
                self.query_to_embedding['passage'][query] = embedding

    def get_fact_scores(self, query: str) -> np.ndarray:
        """
        Retrieves and computes normalized similarity scores between the given query and pre-stored fact embeddings.

        Parameters:
        query : str
            The input query text for which similarity scores with fact embeddings
            need to be computed.

        Returns:
        numpy.ndarray
            A normalized array of similarity scores between the query and fact
            embeddings. The shape of the array is determined by the number of
            facts.

        Raises:
        KeyError
            If no embedding is found for the provided query in the stored query
            embeddings dictionary.
        """
        query_embedding = self.query_to_embedding['triple'].get(query, None)
        if query_embedding is None:
            query_embedding = self.encode_query_embeddings_for_target([query], target="fact")[0]
            self.query_to_embedding['triple'][query] = query_embedding


        if len(self.fact_embeddings) == 0:
            logger.warning("No facts available for scoring. Returning empty array.")
            return np.array([])

        try:
            query_fact_scores = np.dot(self.fact_embeddings, query_embedding.T)
            query_fact_scores = np.squeeze(query_fact_scores) if query_fact_scores.ndim == 2 else query_fact_scores
            query_fact_scores = min_max_normalize(query_fact_scores)
            query_fact_scores = self.apply_ontology_fact_boost(query, query_fact_scores)
            query_fact_scores = self.apply_query_ontology_prior_boost(query, query_fact_scores)
            return query_fact_scores
        except Exception as e:
            logger.error(f"Error computing fact scores: {str(e)}")
            return np.array([])

    def _adaptive_base_sparse_index(self) -> SparseBM25Index:
        index = getattr(self, "_adaptive_base_sparse_bm25", None)
        if isinstance(index, SparseBM25Index):
            return index
        documents = []
        for passage_key in self.passage_node_keys:
            row = self.chunk_embedding_store.get_row(passage_key) or {}
            documents.append(str(row.get("content", "") or ""))
        index = SparseBM25Index(documents)
        self._adaptive_base_sparse_bm25 = index
        return index

    def apply_adaptive_base_access_router(
        self,
        *,
        query: str,
        ppr_doc_ids: Sequence[int],
        ppr_doc_scores: Sequence[float],
        query_fact_scores: Sequence[float],
        top_k_facts: Sequence[Sequence[Any]],
    ) -> Tuple[np.ndarray, np.ndarray, Dict[str, Any]]:
        """Select one complete base ranking before ontology passage planning."""
        enabled = bool(getattr(
            self.global_config, "enable_adaptive_base_access_router", False
        ))
        collect_only = bool(getattr(
            self.global_config, "adaptive_base_access_collect_only", False
        ))
        log: Dict[str, Any] = {
            "enabled": enabled,
            "collect_only": collect_only,
            "selected_path": "ppr",
            "reason": "disabled",
            "dataset_name_is_feature": False,
        }
        ppr_ids = np.asarray(list(ppr_doc_ids), dtype=int)
        ppr_scores = np.asarray(list(ppr_doc_scores), dtype=float)
        if not enabled:
            return ppr_ids, ppr_scores, log

        model_path = str(getattr(
            self.global_config, "adaptive_base_access_model_path", ""
        ) or "")
        router = getattr(self, "_adaptive_base_access_router_model", None)
        if (
            not isinstance(router, AdaptiveBaseAccessRouter)
            or router.model_path != model_path
        ):
            router = AdaptiveBaseAccessRouter(model_path)
            self._adaptive_base_access_router_model = router
        if not collect_only and not router.ready:
            log.update({
                "reason": "model_unavailable",
                "model_ready": False,
                "model_path": model_path,
            })
            return ppr_ids, ppr_scores, log

        dense_ids, dense_scores = self.dense_passage_retrieval(query)
        rankings = {
            "ppr": ppr_ids,
            "dense": np.asarray(dense_ids, dtype=int),
        }
        ranking_scores = {
            "ppr": ppr_scores,
            "dense": np.asarray(dense_scores, dtype=float),
        }
        sparse_enabled = collect_only or "sparse" in router.enabled_paths
        if sparse_enabled:
            sparse_limit = max(int(getattr(
                self.global_config, "adaptive_base_access_sparse_top_k", 200
            )), 5)
            sparse_ids, sparse_scores = self._adaptive_base_sparse_index().search(
                query,
                top_k=min(sparse_limit, len(dense_ids)),
                fallback_ids=dense_ids,
            )
            rankings["sparse"] = np.asarray(sparse_ids, dtype=int)
            ranking_scores["sparse"] = np.asarray(sparse_scores, dtype=float)
        adapter = getattr(self, "query_plan_ontology_adapter", None)
        query_type = (
            adapter.classify_query(query, None)
            if isinstance(adapter, QueryPlanOntologyAdapter)
            else "other"
        )
        features = build_router_features(
            query=query,
            query_type=query_type,
            fact_scores=query_fact_scores,
            top_facts=top_k_facts,
            rankings=rankings,
            ranking_scores=ranking_scores,
        )
        decision = router.decide(features)
        selected_path = "ppr" if collect_only else str(
            decision.get("selected_path", "ppr") or "ppr"
        )
        if selected_path not in ACCESS_PATHS:
            selected_path = "ppr"
        window = max(int(getattr(self.global_config, "retrieval_top_k", 200)), 5)
        log.update({
            "query_type": query_type,
            "features": features,
            "selected_path": selected_path,
            "reason": "collect_only_ppr" if collect_only else decision.get("reason", ""),
            "model_ready": bool(decision.get("model_ready", False)),
            "model_path": model_path,
            "enabled_paths": list(router.enabled_paths),
            "sparse_materialized": sparse_enabled,
            "predictions": decision.get("predictions", {}),
            "policy": {
                key: decision.get(key)
                for key in ("maximum_risk", "minimum_net_gain", "risk_weight")
                if decision.get(key) is not None
            },
            "paths": {
                path: {
                    "doc_ids": [int(value) for value in rankings[path][:window]],
                    "doc_scores": [float(value) for value in ranking_scores[path][:window]],
                }
                for path in rankings
            },
        })
        return rankings[selected_path], ranking_scores[selected_path], log

    def dense_passage_retrieval(self, query: str) -> Tuple[np.ndarray, np.ndarray]:
        """
        Conduct dense passage retrieval to find relevant documents for a query.

        This function processes a given query using a pre-trained embedding model
        to generate query embeddings. The similarity scores between the query
        embedding and passage embeddings are computed using dot product, followed
        by score normalization. Finally, the function ranks the documents based
        on their similarity scores and returns the ranked document identifiers
        and their scores.

        Parameters
        ----------
        query : str
            The input query for which relevant passages should be retrieved.

        Returns
        -------
        tuple : Tuple[np.ndarray, np.ndarray]
            A tuple containing two elements:
            - A list of sorted document identifiers based on their relevance scores.
            - A numpy array of the normalized similarity scores for the corresponding
              documents.
        """
        query_embedding = self.query_to_embedding['passage'].get(query, None)
        if query_embedding is None:
            query_embedding = self.encode_query_embeddings_for_target([query], target="passage")[0]
            self.query_to_embedding['passage'][query] = query_embedding
        query_doc_scores = np.dot(self.passage_embeddings, query_embedding.T)
        query_doc_scores = np.squeeze(query_doc_scores) if query_doc_scores.ndim == 2 else query_doc_scores
        query_doc_scores = min_max_normalize(query_doc_scores)

        sorted_doc_ids = np.argsort(query_doc_scores)[::-1]
        sorted_doc_scores = query_doc_scores[sorted_doc_ids.tolist()]
        return sorted_doc_ids, sorted_doc_scores


    def get_top_k_weights(self,
                          link_top_k: int,
                          all_phrase_weights: np.ndarray,
                          linking_score_map: Dict[str, float]) -> Tuple[np.ndarray, Dict[str, float]]:
        """
        This function filters the all_phrase_weights to retain only the weights for the
        top-ranked phrases in terms of the linking_score_map. It also filters linking scores
        to retain only the top `link_top_k` ranked nodes. Non-selected phrases in phrase
        weights are reset to a weight of 0.0.

        Args:
            link_top_k (int): Number of top-ranked nodes to retain in the linking score map.
            all_phrase_weights (np.ndarray): An array representing the phrase weights, indexed
                by phrase ID.
            linking_score_map (Dict[str, float]): A mapping of phrase content to its linking
                score, sorted in descending order of scores.

        Returns:
            Tuple[np.ndarray, Dict[str, float]]: A tuple containing the filtered array
            of all_phrase_weights with unselected weights set to 0.0, and the filtered
            linking_score_map containing only the top `link_top_k` phrases.
        """

        linking_score_map = dict(sorted(linking_score_map.items(), key=lambda x: x[1], reverse=True)[:link_top_k])


        top_k_phrases = set(linking_score_map.keys())
        top_k_phrases_keys = set(
            [compute_mdhash_id(content=top_k_phrase, prefix="entity-") for top_k_phrase in top_k_phrases])

        for phrase_key in self.node_name_to_vertex_idx:
            if phrase_key not in top_k_phrases_keys:
                phrase_id = self.node_name_to_vertex_idx.get(phrase_key, None)
                if phrase_id is not None:
                    all_phrase_weights[phrase_id] = 0.0

        assert np.count_nonzero(all_phrase_weights) == len(linking_score_map.keys())
        return all_phrase_weights, linking_score_map

    def graph_search_with_fact_entities(self, query: str,
                                        link_top_k: int,
                                        query_fact_scores: np.ndarray,
                                        top_k_facts: List[Tuple],
                                        top_k_fact_indices: List[str],
                                        passage_node_weight: float = 0.05,
                                        extra_passage_weights: Optional[Mapping[int, float]] = None) -> Tuple[np.ndarray, np.ndarray]:
        """
        Computes document scores based on fact-based similarity and relevance using personalized
        PageRank (PPR) and dense retrieval models. This function combines the signal from the relevant
        facts identified with passage similarity and graph-based search for enhanced result ranking.

        Parameters:
            query (str): The input query string for which similarity and relevance computations
                need to be performed.
            link_top_k (int): The number of top phrases to include from the linking score map for
                downstream processing.
            query_fact_scores (np.ndarray): An array of scores representing fact-query similarity
                for each of the provided facts.
            top_k_facts (List[Tuple]): A list of top-ranked facts, where each fact is represented
                as a tuple of its subject, predicate, and object.
            top_k_fact_indices (List[str]): Corresponding indices or identifiers for the top-ranked
                facts in the query_fact_scores array.
            passage_node_weight (float): Default weight to scale passage scores in the graph.

        Returns:
            Tuple[np.ndarray, np.ndarray]: A tuple containing two arrays:
                - The first array corresponds to document IDs sorted based on their scores.
                - The second array consists of the PPR scores associated with the sorted document IDs.
        """


        linking_score_map = {}
        phrase_scores = {}
        phrase_weights = np.zeros(len(self.graph.vs['name']))
        passage_weights = np.zeros(len(self.graph.vs['name']))
        number_of_occurs = np.zeros(len(self.graph.vs['name']))

        phrases_and_ids = set()

        for rank, f in enumerate(top_k_facts):
            subject_phrase = f[0].lower()
            predicate_phrase = f[1].lower()
            object_phrase = f[2].lower()
            fact_score = query_fact_scores[
                top_k_fact_indices[rank]] if query_fact_scores.ndim > 0 else query_fact_scores

            for phrase in [subject_phrase, object_phrase]:
                phrase_key = compute_mdhash_id(
                    content=phrase,
                    prefix="entity-"
                )
                phrase_id = self.node_name_to_vertex_idx.get(phrase_key, None)

                if phrase_id is not None:
                    weighted_fact_score = fact_score

                    if len(self.ent_node_to_chunk_ids.get(phrase_key, set())) > 0:
                        weighted_fact_score /= len(self.ent_node_to_chunk_ids[phrase_key])

                    phrase_weights[phrase_id] += weighted_fact_score
                    number_of_occurs[phrase_id] += 1

                phrases_and_ids.add((phrase, phrase_id))

        phrase_weights = np.divide(
            phrase_weights,
            number_of_occurs,
            out=np.zeros_like(phrase_weights),
            where=number_of_occurs > 0,
        )

        for phrase, phrase_id in phrases_and_ids:
            if phrase not in phrase_scores:
                phrase_scores[phrase] = []

            phrase_scores[phrase].append(phrase_weights[phrase_id])


        for phrase, scores in phrase_scores.items():
            linking_score_map[phrase] = float(np.mean(scores))

        if link_top_k:
            phrase_weights, linking_score_map = self.get_top_k_weights(link_top_k,
                                                                           phrase_weights,
                                                                           linking_score_map)


        dpr_sorted_doc_ids, dpr_sorted_doc_scores = self.dense_passage_retrieval(query)
        normalized_dpr_sorted_scores = min_max_normalize(dpr_sorted_doc_scores)

        for i, dpr_sorted_doc_id in enumerate(dpr_sorted_doc_ids.tolist()):
            passage_node_key = self.passage_node_keys[dpr_sorted_doc_id]
            passage_dpr_score = normalized_dpr_sorted_scores[i]
            passage_node_id = self.node_name_to_vertex_idx[passage_node_key]
            passage_weights[passage_node_id] = passage_dpr_score * passage_node_weight
            passage_node_text = self.chunk_embedding_store.get_row(passage_node_key)["content"]
            linking_score_map[passage_node_text] = passage_dpr_score * passage_node_weight

        for passage_idx, extra_weight in (extra_passage_weights or {}).items():
            try:
                passage_idx = int(passage_idx)
                extra_weight = float(extra_weight)
            except (TypeError, ValueError):
                continue
            if extra_weight <= 0.0 or passage_idx < 0 or passage_idx >= len(self.passage_node_keys):
                continue
            passage_node_key = self.passage_node_keys[passage_idx]
            passage_node_id = self.node_name_to_vertex_idx.get(passage_node_key)
            if passage_node_id is None:
                continue
            passage_weights[passage_node_id] += extra_weight
            linking_score_map[f"ontology_seed::{passage_node_key}"] = extra_weight


        node_weights = phrase_weights + passage_weights


        if len(linking_score_map) > 30:
            linking_score_map = dict(sorted(linking_score_map.items(), key=lambda x: x[1], reverse=True)[:30])

        assert sum(node_weights) > 0, f'No phrases found in the graph for the given facts: {top_k_facts}'


        ppr_start = time.time()
        ppr_sorted_doc_ids, ppr_sorted_doc_scores = self.run_ppr(node_weights, damping=self.global_config.damping)
        ppr_end = time.time()

        self.ppr_time += (ppr_end - ppr_start)

        assert len(ppr_sorted_doc_ids) == len(
            self.passage_node_idxs), f"Doc prob length {len(ppr_sorted_doc_ids)} != corpus length {len(self.passage_node_idxs)}"

        return ppr_sorted_doc_ids, ppr_sorted_doc_scores


    def rerank_facts(self, query: str, query_fact_scores: np.ndarray) -> Tuple[List[int], List[Tuple], dict]:
        """

        Args:

        Returns:
            top_k_fact_indicies:
            top_k_facts:
            rerank_log (dict): {'facts_before_rerank': candidate_facts, 'facts_after_rerank': top_k_facts}
                - candidate_facts (list): list of link_top_k facts (each fact is a relation triple in tuple data type).
                - top_k_facts:


        """

        link_top_k: int = self.global_config.linking_top_k


        if len(query_fact_scores) == 0 or len(self.fact_node_keys) == 0:
            logger.warning("No facts available for reranking. Returning empty lists.")
            return [], [], {'facts_before_rerank': [], 'facts_after_rerank': []}

        try:

            if len(query_fact_scores) <= link_top_k:

                candidate_fact_indices = np.argsort(query_fact_scores)[::-1].tolist()
            else:

                candidate_fact_indices = np.argsort(query_fact_scores)[-link_top_k:][::-1].tolist()


            real_candidate_fact_ids = [self.fact_node_keys[idx] for idx in candidate_fact_indices]
            fact_row_dict = self.fact_embedding_store.get_rows(real_candidate_fact_ids)
            candidate_facts = [eval(fact_row_dict[id]['content']) for id in real_candidate_fact_ids]


            top_k_fact_indices, top_k_facts, reranker_dict = self.rerank_filter(query,
                                                                                candidate_facts,
                                                                                candidate_fact_indices,
                                                                                len_after_rerank=link_top_k)

            rerank_log = {'facts_before_rerank': candidate_facts, 'facts_after_rerank': top_k_facts}

            return top_k_fact_indices, top_k_facts, rerank_log

        except Exception as e:
            logger.error(f"Error in rerank_facts: {str(e)}")
            return [], [], {'facts_before_rerank': [], 'facts_after_rerank': [], 'error': str(e)}

    def run_ppr(self,
                reset_prob: np.ndarray,
                damping: float =0.5) -> Tuple[np.ndarray, np.ndarray]:
        """
        Runs Personalized PageRank (PPR) on a graph and computes relevance scores for
        nodes corresponding to document passages. The method utilizes a damping
        factor for teleportation during rank computation and can take a reset
        probability array to influence the starting state of the computation.

        Parameters:
            reset_prob (np.ndarray): A 1-dimensional array specifying the reset
                probability distribution for each node. The array must have a size
                equal to the number of nodes in the graph. NaNs or negative values
                within the array are replaced with zeros.
            damping (float): A scalar specifying the damping factor for the
                computation. Defaults to 0.5 if not provided or set to `None`.

        Returns:
            Tuple[np.ndarray, np.ndarray]: A tuple containing two numpy arrays. The
                first array represents the sorted node IDs of document passages based
                on their relevance scores in descending order. The second array
                contains the corresponding relevance scores of each document passage
                in the same order.
        """

        if damping is None: damping = 0.5
        reset_prob = np.where(np.isnan(reset_prob) | (reset_prob < 0), 0, reset_prob)
        pagerank_scores = self.graph.personalized_pagerank(
            vertices=range(len(self.node_name_to_vertex_idx)),
            damping=damping,
            directed=False,
            weights='weight',
            reset=reset_prob,
            implementation='prpack'
        )

        doc_scores = np.array([pagerank_scores[idx] for idx in self.passage_node_idxs])
        sorted_doc_ids = np.argsort(doc_scores)[::-1]
        sorted_doc_scores = doc_scores[sorted_doc_ids.tolist()]

        return sorted_doc_ids, sorted_doc_scores
